  <footer class="footer-strip">
    <p>© 2025 Volta Studio</p>
    <p>Function + Feeling</p>
  </footer>

  <script>
    // ── Marquee data ──
    const rows = [
      ['Nexora', 'Pinnacle', 'Orbis', 'Kinetic', 'Lumina', 'Helix'],
      ['Streamline', 'Beacon', 'Prism', 'Zenith', 'Forge', 'Catalyst'],
      ['Vertex', 'Horizon', 'Atlas', 'Meridian', 'Crest', 'Ember']
    ];

    function buildRow(id, names) {
      const track = document.getElementById(id);
      // Build one set, then duplicate for seamless loop
      const set = document.createElement('div');
      set.style.cssText = 'display:flex;align-items:center;';
      names.forEach((name, i) => {
        const item = document.createElement('span');
        item.className = 'marquee-item';
        item.textContent = name;
        set.appendChild(item);
        if (i < names.length - 1 || true) {
          const sep = document.createElement('span');
          sep.className = 'marquee-sep';
          sep.textContent = '◦';
          set.appendChild(sep);
        }
      });
      track.appendChild(set);
      // Clone for seamless
      track.appendChild(set.cloneNode(true));
      track.appendChild(set.cloneNode(true));
      track.appendChild(set.cloneNode(true));
    }

    buildRow('row1', rows[0]);
    buildRow('row2', rows[1]);
    buildRow('row3', rows[2]);

    // ── Mobile menu ──
    const hamburger = document.getElementById('hamburger');
    const mobileMenu = document.getElementById('mobileMenu');
    let menuOpen = false;

    function openMenu() {
      menuOpen = true;
      mobileMenu.style.display = 'flex';
      requestAnimationFrame(() => {
        mobileMenu.classList.add('open');
      });
      hamburger.classList.add('open');
      hamburger.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
    }

    function closeMenu() {
      menuOpen = false;
      mobileMenu.classList.remove('open');
      hamburger.classList.remove('open');
      hamburger.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      setTimeout(() => {
        if (!menuOpen) mobileMenu.style.display = 'none';
      }, 300);
    }

    hamburger.addEventListener('click', () => {
      if (menuOpen) closeMenu(); else openMenu();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && menuOpen) closeMenu();
    });
  </script>
